def _nome_do_tipo(upc) -> str:  # noqa: ANN001
    formato = "Retangular" if "RET" in (upc.tipo_forno or "").upper() else "Circular"
    partes = [formato]
    if upc.diametro_forno_m:
        partes.append(f"{upc.diametro_forno_m} m")
    partes.append(f"{upc.volume_forno_mdc} MDC")
    return " ".join(partes).replace(".", ",")[:60]


def copiar_fornos_das_upcs(apps, schema_editor):  # noqa: ANN001
    """Cria o tipo de forno e os fornos F01..Fnn com os dados que estavam na UPC."""
    UPC = apps.get_model("sistema", "UPC")
    TipoForno = apps.get_model("sistema", "TipoForno")
    Forno = apps.get_model("sistema", "Forno")
    banco = schema_editor.connection.alias
    for upc in UPC.objects.using(banco).all():
        if not upc.numero_fornos:
            continue
        retangular = "RET" in (upc.tipo_forno or "").upper()
        tipo, _ = TipoForno.objects.using(banco).get_or_create(
            empresa_id=upc.empresa_id,
            nome=_nome_do_tipo(upc),
            defaults={
                "formato": "RETANGULAR" if retangular else "CIRCULAR",
                "nivel_mecanizacao": "MANUAL",
                "diametro_m": upc.diametro_forno_m,
                "altura_total_m": upc.altura_total_forno_m,
                "altura_cilindro_m": upc.altura_cilindro_m,
                "capacidade_mdc": upc.volume_forno_mdc,
                "usuario_inclusao_id": upc.usuario_inclusao_id,
                "observacao": "Criado a partir do cadastro da UPC.",
            },
        )
        largura = max(2, len(str(upc.numero_fornos)))
        Forno.objects.using(banco).bulk_create(
            Forno(
                empresa_id=upc.empresa_id,
                upc_id=upc.pk,
                tipo_forno_id=tipo.pk,
                numero=f"F{numero:0{largura}d}",
                usuario_inclusao_id=upc.usuario_inclusao_id,
            )
            for numero in range(1, upc.numero_fornos + 1)
        )


